import{_ as o,o as t,c as r,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"FR 3.6.16 — Sync Material from Google Drive","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/05-content-task-workflow/3-6-16-sync-material-from-google-drive/spec.md","filePath":"feature/srs/05-content-task-workflow/3-6-16-sync-material-from-google-drive/spec.md"}'),i={name:"feature/srs/05-content-task-workflow/3-6-16-sync-material-from-google-drive/spec.md"};function c(n,e,s,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-6-16-—-sync-material-from-google-drive" tabindex="-1">FR 3.6.16 — Sync Material from Google Drive <a class="header-anchor" href="#fr-3-6-16-—-sync-material-from-google-drive" aria-label="Permalink to &quot;FR 3.6.16 — Sync Material from Google Drive&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.6.16</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-068</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Sync Material from Google Drive</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Content &amp; Workflow (<code>FR 3.6</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-36, BR-37</code></td></tr><tr><td style="text-align:left;"><strong>Document Status</strong></td><td style="text-align:left;">Implemented &amp; Verified</td></tr></tbody></table><h2 id="_1-objective-functional-scope" tabindex="-1">1. Objective &amp; Functional Scope <a class="header-anchor" href="#_1-objective-functional-scope" aria-label="Permalink to &quot;1. Objective &amp; Functional Scope&quot;">​</a></h2><p>Đồng bộ và nhập các tệp hình ảnh/video từ thư mục Google Drive đã kết nối vào Material Repository của Workspace (Sync Material from Google Drive — /workspaces/:id/library/drive). Hệ thống kiểm tra phiên kết nối Google Drive hợp lệ, đối chiếu mã định danh tệp để tránh nhập trùng lặp và tự động gắn phân loại tư liệu tương ứng trong kho (BR-36, BR-37).</p><p><strong>Consolidated Implementation Scope:</strong> Folds in <code>client-drive-workspace-sync</code>, <code>client-drive-overflow</code>, and <code>s3-folder-vault-security</code>: executes asynchronous, cancellable one-time Google Drive folder-tree import jobs (<code>DriveFolderImportService</code>) that recursively recreate nested sub-folders in <code>material_folders</code>, validate supported media MIME/magic bytes, pre-encrypt files with <code>RepositoryEnvelopeCrypto</code> into <code>SYSTEM_S3</code>, enforce remaining S3 storage quota (<code>413 STORAGE_QUOTA_EXCEEDED</code> graceful overflow handling without partial corruption), and track real-time job progress (<code>importedCount</code>, <code>skippedCount</code>, <code>failedCount</code>, <code>BR-36</code>, <code>BR-37</code>).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized actor (<code>Owner, Manager, Client</code>), I want to execute <strong>Sync Material from Google Drive</strong> within my active Workspace with strict role/audience isolation, version/concurrency safety, and responsive feedback, so that content production workflows satisfy <code>BR-36, BR-37</code> across Web and Mobile.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Workspace &amp; Role Authorization:</strong> Only authenticated actors holding <code>Owner, Manager, Client</code> in the target Workspace (plus <code>Guest</code> solely on public survey token endpoints in <code>3.6.25</code>) may invoke <code>POST /api/v1/workspaces/{workspaceId}/materials/drive-import · GET /api/v1/workspaces/{workspaceId}/materials/drive-import/{jobId} · POST /api/v1/workspaces/{workspaceId}/materials/drive-import/{jobId}/cancel</code>; revoked or cross-workspace callers are rejected (<code>401</code> / <code>403</code>).</li><li><strong>Core Domain &amp; Security Invariants (<code>BR-36, BR-37</code>):</strong> <code>DriveFolderImportService, CustomerDriveSyncService, CustomerDriveImportStore, RepositoryEnvelopeCrypto, StorageQuotaService</code> enforces all state-machine locks, audience visibility filters (<code>INTERNAL</code> vs per-<code>clientProfileId</code> <code>CLIENT</code>), storage/file validation rules, and Workspace timezone boundaries (<code>Asia/Ho_Chi_Minh</code> default).</li><li><strong>Persistence &amp; Envelope Contract:</strong> Operations on MongoDB <code>materials</code>, <code>material_folders</code>, <code>drive_import_jobs</code>; AWS S3 (<code>SYSTEM_S3</code>) return standardized <code>ApiResponse&lt;T&gt;</code> payloads (or authenticated binary/WebSocket frames where applicable) with deterministic <code>ErrorCode</code> mappings (<code>400 INVALID_DRIVE_FOLDER</code>, <code>403 FORBIDDEN</code>, <code>409 DRIVE_IMPORT_ALREADY_RUNNING</code>, <code>413 STORAGE_QUOTA_EXCEEDED</code> (<code>BR-36</code>, <code>BR-37</code>)).</li><li><strong>Internationalization (<code>vi</code> / <code>en</code>):</strong> Every label, badge, filter pill, modal prompt, empty state, and error toast uses parallel translation keys (<code>library.drive.import.*</code>) in <code>src/i18n/locales/vi/*.json</code> and <code>en/*.json</code> — zero hardcoded UI text.</li><li><strong>Semantic Light/Dark Theme &amp; Accessibility:</strong> Web (<code>src/pages/library/components/CustomerDrivePanel.tsx</code>, <code>src/components/common/BackgroundTaskDock.tsx</code>, <code>src/services/materialService.ts</code>) and Mobile (<code>src/screens/more/MediaLibraryScreen.tsx</code>, <code>src/services/mediaSyncService.ts</code>) components use semantic CSS variables / <code>dark:</code> Tailwind tokens and <code>useTheme()</code> tokens, supporting keyboard navigation (<code>Enter</code>/<code>Escape</code>/focus return) and mobile viewports.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surface (<code>brandhub-web</code>):</strong> <code>src/pages/library/components/CustomerDrivePanel.tsx</code>, <code>src/components/common/BackgroundTaskDock.tsx</code>, <code>src/services/materialService.ts</code></li><li><strong>Mobile Surface (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/MediaLibraryScreen.tsx</code>, <code>src/services/mediaSyncService.ts</code></li><li><strong>Required UI States:</strong><ul><li><strong>Loading / Pending:</strong> Skeleton placeholders, progress indicators for uploads/imports, and disabled duplicate-submit triggers.</li><li><strong>Empty State:</strong> Clear localized explanation with role-appropriate CTA — never substituting synthetic mock items.</li><li><strong>Conflict / Warning:</strong> Preserves unsaved user drafts on <code>409</code> conflicts and surfaces inline warnings (such as <code>RAW</code> unedited photo badges or compliance warnings).</li><li><strong>Error / Retry:</strong> Actionable inline/banner error state with retry capability.</li></ul></li></ul><h2 id="_5-api-realtime-contract" tabindex="-1">5. API &amp; Realtime Contract <a class="header-anchor" href="#_5-api-realtime-contract" aria-label="Permalink to &quot;5. API &amp; Realtime Contract&quot;">​</a></h2><ul><li><strong>Endpoints / Channels:</strong> <code>POST /api/v1/workspaces/{workspaceId}/materials/drive-import · GET /api/v1/workspaces/{workspaceId}/materials/drive-import/{jobId} · POST /api/v1/workspaces/{workspaceId}/materials/drive-import/{jobId}/cancel</code></li><li><strong>Controllers (<code>brandhub-business-service</code>):</strong> <code>DriveFolderImportController.start() / status() / cancel()</code></li><li><strong>Services:</strong> <code>DriveFolderImportService, CustomerDriveSyncService, CustomerDriveImportStore, RepositoryEnvelopeCrypto, StorageQuotaService</code></li><li><strong>Repositories / Stores:</strong> CustomerDriveImportStore, MaterialMongoRepository (<code>materials</code>, <code>material_folders</code>), StorageQuotaService</li></ul><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Domain Error Codes:</strong> <code>400 INVALID_DRIVE_FOLDER</code>, <code>403 FORBIDDEN</code>, <code>409 DRIVE_IMPORT_ALREADY_RUNNING</code>, <code>413 STORAGE_QUOTA_EXCEEDED</code> (<code>BR-36</code>, <code>BR-37</code>).</li><li><strong>Audience &amp; Removed-Member Isolation:</strong> Removed or deactivated Workspace members lose read/write/WebSocket access immediately on the next request or STOMP frame; <code>Client</code> actors never see <code>INTERNAL</code>-only materials or other <code>ClientProfile</code> assets.</li><li><strong>Idempotency &amp; Concurrency:</strong> Optimistic revision checks (<code>workflowRevision</code>, <code>revision</code>, <code>clientMessageId</code>, <code>DriveOperationLease</code>) prevent race-condition overwrites and duplicate records on retry.</li></ul><h2 id="_7-definition-of-done-cross-references" tabindex="-1">7. Definition of Done &amp; Cross-References <a class="header-anchor" href="#_7-definition-of-done-cross-references" aria-label="Permalink to &quot;7. Definition of Done &amp; Cross-References&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Backend endpoints/handlers verified by automated tests (<a href="./test.html">test.md</a>), Web &amp; Mobile UI integrated against live APIs, <code>vi</code>/<code>en</code> locale parity verified, and Light/Dark themes verified.</li><li><strong>Out of Scope:</strong> Adjacent workflow capabilities covered by sibling FRs in <code>3.6.1–3.6.35</code> and social publishing execution in <code>3.8.1–3.8.15</code>.</li><li><strong>Related Documentation:</strong> <a href="./../../../../ba/05-content-task-workflow.html">BA Content &amp; Workflow Spec</a> · <a href="./../../../../ba/12-state-machines.html">State Machines</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul>',18)])])}const u=o(i,[["render",c]]);export{g as __pageData,u as default};
